function gh(author, repo, day, opts) {
  const id = `${author}-${repo}`.toLowerCase().replace(/[^a-z0-9]+/g, "-");
  const url = `https://github.com/${author}/${repo}`;
  return {
    id,
    name: opts.name ?? repo,
    description: opts.description,
    longDescription: opts.longDescription,
    resourceType: opts.resourceType,
    visualStyle: opts.visualStyle,
    family: opts.family,
    tags: opts.tags,
    author,
    sourceUrl: url,
    stars: opts.stars ?? 0,
    installCommand: `git clone ${url}.git`,
    featured: opts.featured ?? false,
    createdAt: daysAgo(day + 10),
    updatedAt: daysAgo(day),
    difficulty: opts.difficulty ?? "\u5165\u95E8",
    language: opts.language ?? "zh"
  };
}
function ghDoc(author, repo, path, day, description, longDescription, family, tags = ["\u901A\u7528"]) {
  const id = `${author}-${repo}-${path}`.toLowerCase().replace(/[^a-z0-9]+/g, "-");
  const url = `https://github.com/${author}/${repo}/blob/main/${path}`;
  return {
    id,
    name: path.split("/").pop() || path,
    description,
    longDescription,
    resourceType: "template",
    family,
    tags,
    author,
    sourceUrl: url,
    stars: 0,
    installCommand: `\u67E5\u770B\u6587\u6863\uFF1A${url}`,
    featured: false,
    createdAt: daysAgo(day + 10),
    updatedAt: daysAgo(day),
    difficulty: "\u5165\u95E8",
    language: "zh"
  };
}
function link(id, name, description, longDescription, sourceUrl, resourceType, tags, day, extra) {
  return {
    id,
    name,
    description,
    longDescription,
    resourceType,
    family: id,
    tags,
    author: "\u793E\u533A",
    sourceUrl,
    stars: 0,
    featured: false,
    createdAt: daysAgo(day + 10),
    updatedAt: daysAgo(day),
    difficulty: "\u5165\u95E8",
    language: "zh",
    ...extra
  };
}
